begin;
do $$declare tid uuid;lead uuid;member uuid;role_name text;r jsonb;t uuid;denied boolean;before_members integer;begin
 select t.id,t.coordinator_id into tid,lead from public.website_project_teams t where t.status='active' and t.lab_enabled and private_website_lab.market_leader(t.id,t.coordinator_id) limit 1;
 member:=gen_random_uuid();insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values(member,'recruitment-social-qa-'||member||'@example.test',now(),'{}');
 assert tid is not null;select jsonb_array_elements_text(roles) into role_name from public.website_project_briefs where project_ref=(select project_ref from public.website_project_teams where id=tid) limit 1;
 insert into private_website_lab.market_recruitment(team_id,collaborator_capacity,open,description,roles,skills,commitment) values(tid,12,true,'[SOCIAL-QA] An authorised synthetic recruitment summary.',array[role_name],array['SQL'],'Two hours weekly') on conflict(team_id) do update set collaborator_capacity=12,open=true,description=excluded.description,roles=excluded.roles,skills=excluded.skills,commitment=excluded.commitment;
 perform set_config('test.recruit.team',tid::text,true);perform set_config('test.recruit.lead',lead::text,true);perform set_config('test.recruit.member',member::text,true);
 perform set_config('request.jwt.claim.sub',member::text,true);
 denied:=false;begin perform public.website_recruitment_sharing('enable',jsonb_build_object('team_id',tid,'approved_public',true));exception when insufficient_privilege then denied:=true;end;assert denied,'Member enabled another leader social sharing';
 assert public.website_recruitment_sharing('link',jsonb_build_object('team_id',tid))->>'available'='false','Recruitment became externally public without approval';
 perform set_config('request.jwt.claim.sub',lead::text,true);
 denied:=false;begin perform public.website_recruitment_sharing('enable',jsonb_build_object('team_id',tid));exception when raise_exception then denied:=true;end;assert denied,'Public permission confirmation bypassed';
 select count(*) into before_members from public.website_project_team_members;
 r:=public.website_recruitment_sharing('enable',jsonb_build_object('team_id',tid,'approved_public',true));t:=(r->>'token')::uuid;
 assert (public.website_recruitment_sharing('enable',jsonb_build_object('team_id',tid,'approved_public',true))->>'token')::uuid=t,'Retry changed an unchanged approved share';
 assert (select count(*) from public.website_project_team_members)=before_members,'Sharing admitted a member';
 perform set_config('test.recruit.token',t::text,true);
end $$;
set local role anon;
do $$declare r jsonb;begin
 r:=public.website_public_recruitment_share(current_setting('test.recruit.token')::uuid);
 assert r->>'description'='[SOCIAL-QA] An authorised synthetic recruitment summary.';
 assert not (r ?| array['team_id','coordinator_id','author_id','approved_by','member_ids','repository_url','private_notes']),'Private Lab details leaked';
 assert (r->>'available')::integer>0;
 assert not has_table_privilege('anon','private_market_shares.recruitment','SELECT');
 assert not has_function_privilege('anon','public.website_recruitment_sharing(text,jsonb)','EXECUTE');
 assert not has_function_privilege('anon','private_market_shares.current_public(uuid)','EXECUTE');
end $$;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('test.recruit.member'),true);
do $$declare r jsonb;begin
 r:=public.website_recruitment_sharing('link',jsonb_build_object('team_id',current_setting('test.recruit.team')));
 assert r->>'available'='true' and r->>'token'=current_setting('test.recruit.token'),'Members could not share approved recruitment';
 assert public.website_recruitment_sharing('resolve',jsonb_build_object('token',current_setting('test.recruit.token')))->>'team_id'=current_setting('test.recruit.team');
end $$;
reset role;
update private_website_lab.market_recruitment set description='[SOCIAL-QA] Changed member-only text; not approved outside Market.' where team_id=current_setting('test.recruit.team')::uuid;
do $$begin assert public.website_public_recruitment_share(current_setting('test.recruit.token')::uuid) is null,'Changed text became public without reapproval';end $$;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('test.recruit.lead'),true);
do $$declare r jsonb;begin
 r:=public.website_recruitment_sharing('enable',jsonb_build_object('team_id',current_setting('test.recruit.team'),'approved_public',true));
 assert r->>'token'<>current_setting('test.recruit.token'),'Revoked token was reactivated';perform set_config('test.recruit.token2',r->>'token',true);
 perform public.website_recruitment_sharing('disable',jsonb_build_object('team_id',current_setting('test.recruit.team')));
 assert public.website_public_recruitment_share((r->>'token')::uuid) is null,'Disabled recruitment stayed public';
 r:=public.website_recruitment_sharing('enable',jsonb_build_object('team_id',current_setting('test.recruit.team'),'approved_public',true));
 assert r->>'token'<>current_setting('test.recruit.token2');perform set_config('test.recruit.current',r->>'token',true);
end $$;
reset role;
savepoint recruitment_state;
update public.website_project_teams set status='paused' where id=current_setting('test.recruit.team')::uuid;
do $$begin assert public.website_public_recruitment_share(current_setting('test.recruit.current')::uuid) is null,'Paused Lab still recruiting publicly';end $$;
rollback to savepoint recruitment_state;
update public.website_project_team_members set admitted_at=null where team_id=current_setting('test.recruit.team')::uuid and user_id=current_setting('test.recruit.lead')::uuid;
do $$begin assert public.website_public_recruitment_share(current_setting('test.recruit.current')::uuid) is null,'Revoked leader access left public recruitment';end $$;
rollback to savepoint recruitment_state;
update private_website_lab.market_recruitment set open=false where team_id=current_setting('test.recruit.team')::uuid;
do $$begin assert public.website_public_recruitment_share(current_setting('test.recruit.current')::uuid) is null,'Closed recruitment still public';end $$;
select 'Recruitment social sharing: leader authority, consent, private-by-default, safe anonymous projection, member sharing, unchanged admission, idempotency, edit/revoke token rotation, pause, access revocation and closure passed.' result;
rollback;
